package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total (at most the sheet's cap) and
 * overdue-total, and the sheet's claimed-total, due-total and overdue-total. A change takes them before it alters anything and hands them back after, and
 * every figure it moved is written to the audit after the change's own lines. Called within the change's
 * transaction.
 */
@Service
public class RollupService {

    /** Shown in place of a due-total whose grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** A person's figures, as the screen shows them. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {}

    /** The sheet's figures at one moment: each person's by id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {}

    /** What a claim's late charge goes by: the sheet's today (none when there is no such sheet) and the sheet,
     * for its late percent and floor in force on a claim's date; and the date its rounding goes by, the policy
     * date or else the sheet's today. */
    private record Lateness(LocalDate today, Sheet sheet, LocalDate policyDate) {

        static Lateness of(Sheet sheet) {
            return sheet == null ? new Lateness(null, null, null)
                    : new Lateness(sheet.getToday(), sheet, sheet.roundingDate());
        }

        /** The late percent in force on a claim's date. */
        BigDecimal latePct(Claim claim) {
            return sheet == null ? BigDecimal.ZERO : sheet.latePctOn(claim.getDate());
        }

        /** The floor in force on a claim's date; 1.00, the one a sheet starts with, when there is no such sheet. */
        BigDecimal floor(Claim claim) {
            return sheet == null ? Sheet.STARTING_FLOOR : sheet.floorOn(claim.getDate());
        }

        /** How a claim's live figures round, by the date they go by: one before the policy date rounds half up,
         * one on or after it half to even. */
        RoundingMode rounding(LocalDate roundsBy) {
            return policyDate != null && roundsBy.isBefore(policyDate) ? RoundingMode.HALF_UP
                    : RoundingMode.HALF_EVEN;
        }
    }

    /** The days in each period an overdue claim gains its late percent for. */
    private static final int LATE_PERIOD_DAYS = 30;

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
    public Snapshot snapshot(String sheetId) {
        Lateness late = latenessOf(sheetId);
        LocalDate today = late.today();
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        for (Claim claim : all) {
            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
        }
        Map<String, LocalDate> datesByNumber = datesByNumber(all);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
                    .filter(c -> counts(c, person)).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean frozen = false;
            for (Claim claim : counted) {
                claimed = claimed.add(claim.getAmount().setScale(2));
                BigDecimal figure = dueOf(claim, ratesOn(person, claim.getDate(), byGrade), late,
                        roundsBy(claim, datesByNumber));
                frozen |= figure != null;
                if (figure != null) {
                    due = due.add(figure.setScale(2));
                    if (overdue(claim, today)) {
                        overdue = overdue.add(figure.setScale(2));
                    }
                }
            }
            // Like the screen: with no rate in force today and no claim having a figure (kept, or at a rate that
            // applies on its date), the due-total is n/a.
            boolean rated = rated(person, counted, today, byGrade);
            if (sheet != null) {
                due = sheet.capped(due);
            }
            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
            claimedTotal = claimedTotal.add(claimed);
            if (rated || frozen) {
                dueTotal = dueTotal.add(due);
            }
            overdueTotal = overdueTotal.add(overdue);
            figures.put(person.getId(),
                    new Figures(person.getName(), claimed.toPlainString(), personDue, overdue.toPlainString()));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString(),
                overdueTotal.toPlainString());
    }

    /** A person's due-total held to the sheet's cap; none (n/a) is not capped. */
    public BigDecimal capped(String sheetId, BigDecimal dueTotal) {
        return sheets.findById(sheetId).map(s -> s.capped(dueTotal)).orElse(dueTotal);
    }

    /** Each person's due-total of their claims that count (OPEN and PENDING ones within a hold, unbound, do not)
     * dated from and to, inclusive, by person id: the sum of their dues, late charges included, n/a ones skipped;
     * a person with no such due has none. */
    public Map<Long, BigDecimal> dueTotals(String sheetId, LocalDate from, LocalDate to) {
        Lateness late = latenessOf(sheetId);
        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            byId.put(person.getId(), person);
        }
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<String, LocalDate> datesByNumber = datesByNumber(all);
        for (Claim claim : all) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !counts(claim, person)
                    || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal figure = dueOf(claim, ratesOn(person, claim.getDate(), byGrade), late,
                    roundsBy(claim, datesByNumber));
            if (figure != null) {
                totals.merge(person.getId(), figure.setScale(2), BigDecimal::add);
            }
        }
        return totals;
    }

    /**
     * Write to the audit, once the change commits, one ROLLUP line for each person whose figures moved since
     * {@code before} (a person new since then counts as moved), in the order they were added, then a TOTALS
     * line when the sheet's totals moved.
     */
    public void recordChanges(String user, String sheetId, Snapshot before) {
        claims.flush();
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            Figures was = before.people().get(e.getKey());
            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())
                    && was.overdueTotal().equals(now.overdueTotal())) {
                continue;
            }
            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
                    + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }

    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to
     * (while not PENDING), else what is due at the rate of the grade its person has on its date, raised to the sheet's floor in force on its date; none
     * when that is n/a. */
    public BigDecimal figureOf(Claim claim, Person person) {
        Lateness late = latenessOf(claim.getSheetId());
        return figureOf(claim, gradeRates(claim, person), late.floor(claim), late.rounding(roundsBy(claim)));
    }

    /** What is due on a claim now: its figure, plus the late charge an overdue claim has on it; none when the
     * figure is n/a. A settled claim's due is the figure it was settled at, the charge it had then frozen in. */
    public BigDecimal dueOf(Claim claim, Person person) {
        return dueOf(claim, gradeRates(claim, person), latenessOf(claim.getSheetId()), roundsBy(claim));
    }

    /** What would be due on a claim today as an OPEN claim bound by no statement: its live figure at the rate its
     * grade has on its date, raised to the sheet's floor in force on its date, plus the late charge it would have; none when that is
     * n/a. Re-settling freezes a claim at this. */
    public BigDecimal openDueOf(Claim claim, Person person) {
        Lateness late = latenessOf(claim.getSheetId());
        RoundingMode rounding = late.rounding(roundsBy(claim));
        BigDecimal figure = liveDueOf(claim, gradeRates(claim, person), late.floor(claim), rounding);
        return figure == null ? null : figure.add(lateCharge(claim, true, figure, late, rounding));
    }

    /** The date a claim's rounding goes by: a correction's is the date of the claim it corrects, any other's its
     * own. */
    private LocalDate roundsBy(Claim claim) {
        return claim.getCorrects() == null ? claim.getDate()
                : roundsBy(claim, datesByNumber(claims.findBySheetIdAndPersonId(claim.getSheetId(),
                        claim.getPersonId())));
    }

    private static LocalDate roundsBy(Claim claim, Map<String, LocalDate> datesByNumber) {
        return claim.getCorrects() == null ? claim.getDate()
                : datesByNumber.getOrDefault(claim.getCorrects(), claim.getDate());
    }

    /** The dates of the claims given that have a number, by number. */
    private static Map<String, LocalDate> datesByNumber(List<Claim> given) {
        Map<String, LocalDate> by = new HashMap<>();
        for (Claim claim : given) {
            if (claim.getNumber() != null) {
                by.put(claim.getNumber(), claim.getDate());
            }
        }
        return by;
    }

    /**
     * Whether a person's due-total has a rate to go by on the sheet's today: the grade they have in force today,
     * or one they had on the date of a claim of theirs that counts, has a rate in force today.
     */
    public boolean rated(Person person, List<Claim> counted, LocalDate today) {
        return rated(person, counted, today, ratesByGrade(person.getSheetId()));
    }

    private static boolean rated(Person person, List<Claim> counted, LocalDate today,
            Map<String, List<Rate>> byGrade) {
        if (today == null) {
            return false;
        }
        Set<String> grades = new HashSet<>();
        grades.add(person.gradeOn(today));
        for (Claim claim : counted) {
            grades.add(person.gradeOn(claim.getDate()));
        }
        return grades.stream().anyMatch(g -> Rate.inForce(byGrade.getOrDefault(g, List.of()), today).isPresent());
    }

    /** The rates of the grade the claim's person has on the claim's date. */
    private List<Rate> gradeRates(Claim claim, Person person) {
        return rates.findBySheetIdAndGrade(claim.getSheetId(), person.gradeOn(claim.getDate()));
    }

    /** The rates of the grade a person has on a date. */
    private static List<Rate> ratesOn(Person person, LocalDate date, Map<String, List<Rate>> byGrade) {
        return byGrade.getOrDefault(person.gradeOn(date), List.of());
    }

    /** The sheet's rates by grade. */
    private Map<String, List<Rate>> ratesByGrade(String sheetId) {
        Map<String, List<Rate>> by = new HashMap<>();
        for (Rate rate : rates.findBySheetId(sheetId)) {
            by.computeIfAbsent(rate.getGrade(), k -> new ArrayList<>()).add(rate);
        }
        return by;
    }

    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, Lateness late, LocalDate roundsBy) {
        RoundingMode rounding = late.rounding(roundsBy);
        BigDecimal figure = figureOf(claim, gradeRates, late.floor(claim), rounding);
        return figure == null ? null : figure.add(lateCharge(claim, claim.getStatus().isOpen(), figure, late, rounding));
    }

    /**
     * The late charge on a claim: the late percent in force on its date of its figure for every full 30 days it is overdue (OPEN or
     * PENDING, and its due-by, fixed when it was added, before the sheet's today), rounded to two decimals as the claim rounds.
     * A statement never binds it: it follows the sheet's today. A correction has none.
     */
    private static BigDecimal lateCharge(Claim claim, boolean open, BigDecimal figure, Lateness late,
            RoundingMode rounding) {
        if (!open || late.today() == null || claim.isCorrection()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdueDays = ChronoUnit.DAYS.between(claim.getDueBy(), late.today());
        long periods = overdueDays > 0 ? overdueDays / LATE_PERIOD_DAYS : 0;
        return figure.multiply(late.latePct(claim)).multiply(BigDecimal.valueOf(periods))
                .divide(BigDecimal.valueOf(100), 2, rounding);
    }

    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return bound(claim) ? claim.getStatedDue() : liveDueOf(claim, gradeRates, floor, rounding);
    }

    /** What is due on a claim at the rate its grade has in force on the claim's date, rounded to two decimals as
     * the claim rounds, and at least the floor in force on its date (a correction has no floor); none when no rate of the grade applies
     * then. */
    private static BigDecimal liveDueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
        BigDecimal amount = claim.getAmount();
        return Rate.inForce(gradeRates, claim.getDate())
                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, rounding))
                .map(due -> claim.isCorrection() ? due : due.max(floor.setScale(2)))
                .orElse(null);
    }

    private Lateness latenessOf(String sheetId) {
        return Lateness.of(sheets.findById(sheetId).orElse(null));
    }

    /** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound,
     * but shows its live figure, and is bound again if it is rejected. */
    private static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
    private static boolean overdue(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && today != null && claim.getDueBy().isBefore(today);
    }

    /** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due; an OPEN or PENDING one dated
     * within one of its person's holds does not, unless it is bound by a statement. */
    public static boolean counts(Claim claim, Person person) {
        return (claim.getStatus().isOpen() && (bound(claim) || !person.heldOn(claim.getDate())))
                || claim.getStatus() == ClaimStatus.SETTLED;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The claims people make on a sheet. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** The amount is a number with up to two decimals, negative for a correction, which names by number the
     * settled claim it corrects; no date means the sheet's today. */
    public record ClaimForm(
            @NotNull @Pattern(regexp = "-?\\d{1,10}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 255) String corrects) {}

    /** The amount is shown with two decimals; a claim has no number until it is opened, and no fixed due
     * until it is settled; it shows who opened it, if anyone did, and whether it is bound to the figure it had
     * at its person's last statement (none when that was n/a); a correction shows the number it corrects; and the
     * date it is due by, fixed when it was added; and its status log, oldest first. */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String due, String openedBy, boolean stated, String statedDue,
            String corrects, LocalDate dueBy, List<StatusLogView> statusLog) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2).toPlainString(), claim.getDate(), claim.getNote(), claim.getStatus(),
                    claim.getNumber(),
                    claim.getSettledDue() != null ? claim.getSettledDue().setScale(2).toPlainString() : null,
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() != null ? claim.getStatedDue().setScale(2).toPlainString() : null,
                    claim.getCorrects(), claim.getDueBy(),
                    claim.getStatusLog().stream().map(StatusLogView::of).toList());
        }
    }

    /** A line of a claim's status log: the status, who changed it, the sheet's today then, and the due then
     * with two decimals, or n/a. */
    public record StatusLogView(ClaimStatus status, String by, LocalDate on, String due) {

        public static StatusLogView of(StatusLogLine line) {
            return new StatusLogView(line.getStatus(), line.getBy(), line.getOn(), line.getDue());
        }
    }

    /** The claims to open, or settle, together, by id. */
    public record OpenAllForm(@NotNull @Size(max = 1000) List<@NotNull Long> ids) {}

    /** How many of the claims were opened and how many refused, and the opened claims as they are now. */
    public record OpenedAllView(int opened, int refused, List<ClaimView> claims) {}

    /** How many of the claims were settled (or sent PENDING) and how many refused, and those claims as they are
     * now. */
    public record SettledAllView(int settled, int refused, List<ClaimView> claims) {}

    /** Why a steward rejects a PENDING claim: one word or more, with no line break. */
    public record RejectForm(@NotBlank @Size(max = 255) @Pattern(regexp = "[^\\r\\n]*") String reason) {}

    /** The person a claim is moved to, by id. */
    public record ReassignForm(@NotNull Long personId) {}

    private final ClaimService service;

    public ClaimController(ClaimService service) {
        this.service = service;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return service.list(sheetId).stream().map(ClaimView::of).toList();
    }

    @PostMapping("/people/{personId}/claims")
    public ClaimView add(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long personId, @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.add(user, sheetId, personId, new BigDecimal(form.amount()), form.date(), form.note(),
                form.corrects()));
    }

    @PutMapping("/claims/{id}")
    public ClaimView update(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.update(user, sheetId, id, new BigDecimal(form.amount()), form.date(), form.note(),
                form.corrects()));
    }

    @PostMapping("/claims/{id}/open")
    public ClaimView open(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/open")
    public OpenedAllView openAll(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody OpenAllForm form) {
        ClaimService.OpenedAll result = service.openAll(user, sheetId, form.ids());
        return new OpenedAllView(result.opened(), result.refused(),
                result.claims().stream().map(ClaimView::of).toList());
    }

    @PostMapping("/claims/settle")
    public SettledAllView settleAll(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody OpenAllForm form) {
        ClaimService.OpenedAll result = service.settleAll(user, sheetId, form.ids());
        return new SettledAllView(result.opened(), result.refused(),
                result.claims().stream().map(ClaimView::of).toList());
    }

    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{id}/approve")
    public ClaimView approve(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id) {
        return ClaimView.of(service.approve(user, sheetId, id));
    }

    @PostMapping("/claims/{id}/resettle")
    public ClaimView resettle(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id) {
        return ClaimView.of(service.resettle(user, sheetId, id));
    }

    @PostMapping("/claims/{id}/reject")
    public ClaimView reject(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id,
            @Valid @RequestBody RejectForm form) {
        return ClaimView.of(service.reject(user, sheetId, id, form.reason()));
    }

    @PostMapping("/claims/{id}/reassign")
    public ClaimView reassign(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody ReassignForm form) {
        return ClaimView.of(service.reassign(user, sheetId, id, form.personId()));
    }

    @PostMapping("/claims/{id}/void")
    public ClaimView voidClaim(@RequestHeader("X-User") String user, @PathVariable String sheetId, @PathVariable Long id) {
        return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.VOID));
    }
}

package net.officefloor.hq.app.sheet;


/** A sheet, kept by the id typed to load it. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The keys the dated settings are kept by; a grade's own terms are kept by {@link #gradeTermsKey}. */
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";

    /** The values a sheet starts with, in force before every from-date. */
    public static final BigDecimal STARTING_FLOOR = new BigDecimal("1.00");
    public static final int STARTING_TERMS = 14;
    public static final BigDecimal STARTING_LATE_PCT = new BigDecimal("0.00");

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's own today: every date-dependent decision on the sheet uses it, never the clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last number given to a claim opened on the sheet; 0 before the first. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The values of the settings that carry a figure (the clerk limit, the floor, the terms and each grade's,
     * the late percent and the cap), each from its from-date until the next of the same key. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_setting_from", joinColumns = @JoinColumn(name = "sheet_id"))
    private List<SettingFrom> dated = new ArrayList<>();

    /** A claim dated before it rounds half up, one dated on or after it half to even; none means the sheet's
     * today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** While a date and the sheet's today is on or after it, a claim opened is numbered within its period; none
     * means off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {}

    public Sheet(String id, String createdBy, Instant createdAt) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = LocalDate.ofInstant(createdAt, ZoneId.systemDefault());
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** The values a dated setting has, by from-date, the one with no from-date first. */
    public List<SettingFrom> history(String key) {
        return dated.stream().filter(d -> d.getKey().equals(key)).sorted(SettingFrom.BY_FROM).toList();
    }

    /** The value a dated setting has in force on a date: the one with the latest from-date on or before it,
     * else {@code starting}, the value a sheet starts with; none where the setting allows it. */
    public BigDecimal valueOn(String key, LocalDate date, BigDecimal starting) {
        return history(key).stream()
                .filter(d -> d.getFrom() == null || !d.getFrom().isAfter(date))
                .max(SettingFrom.BY_FROM)
                .map(SettingFrom::getValue)
                .orElse(starting);
    }

    /** Record the value a dated setting has from a date, replacing one already recorded from that date. */
    public void record(String key, LocalDate from, BigDecimal value) {
        dated.removeIf(d -> d.getKey().equals(key) && Objects.equals(d.getFrom(), from));
        dated.add(new SettingFrom(key, from, value));
    }

    /** The highest due a clerk may settle in force on the sheet's today; none means no limit. */
    public BigDecimal getClerkLimit() {
        return valueOn(CLERK_LIMIT, today, null);
    }

    /** The least a claim's live due comes to in force on a date. */
    public BigDecimal floorOn(LocalDate date) {
        return valueOn(FLOOR, date, STARTING_FLOOR).setScale(2);
    }

    /** The floor in force on the sheet's today. */
    public BigDecimal getFloor() {
        return floorOn(today);
    }

    /** The sheet's own terms in force on a date: the days after its date a claim is due by. */
    public int termsOn(LocalDate date) {
        return valueOn(TERMS, date, BigDecimal.valueOf(STARTING_TERMS)).intValue();
    }

    /** The sheet's own terms in force on the sheet's today. */
    public int getTerms() {
        return termsOn(today);
    }

    /** The grade's own terms in force on the sheet's today; none when it uses the sheet's. */
    public Integer getGradeTerms(String grade) {
        BigDecimal days = valueOn(gradeTermsKey(grade), today, null);
        return days != null ? days.intValue() : null;
    }

    /** The terms a claim of a person of the grade dated on a date is due by: the grade's own in force then, else
     * the sheet's in force then. */
    public int termsFor(String grade, LocalDate date) {
        BigDecimal days = valueOn(gradeTermsKey(grade), date, null);
        return days != null ? days.intValue() : termsOn(date);
    }

    /** The key a grade's own terms are kept by. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** The percent of its figure an overdue claim dated on a date gains for every full 30 days it is overdue. */
    public BigDecimal latePctOn(LocalDate date) {
        return valueOn(LATE_PCT, date, STARTING_LATE_PCT).setScale(2);
    }

    /** The late percent in force on the sheet's today. */
    public BigDecimal getLatePct() {
        return latePctOn(today);
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** The most a person's due-total comes to in force on the sheet's today; none means no cap. */
    public BigDecimal getCap() {
        return valueOn(CAP, today, null);
    }

    /** A person's due-total held to the cap: the cap when it is above it, else as it is; none (n/a) stays none. */
    public BigDecimal capped(BigDecimal dueTotal) {
        BigDecimal cap = getCap();
        return dueTotal != null && cap != null && dueTotal.compareTo(cap) > 0 ? cap.setScale(2) : dueTotal;
    }

    /** Whether a claim opened now is numbered within its period: the period numbering date is set and the
     * sheet's today is on or after it. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** The date the claim rounding goes by: the policy date, or the sheet's today when there is none. */
    public LocalDate roundingDate() {
        return policyDate != null ? policyDate : today;
    }
}
