@Injectable({ providedIn: 'root' })
export class SheetPolicyDate {
  private readonly _value = signal<string | null>(null);
  readonly value = this._value.asReadonly();

  set(policyDate: string | null): void {
    this._value.set(policyDate);
  }
}

